-- Pricing SQL Server schema and future-feature tables
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;

IF COL_LENGTH('dbo.users','email') IS NULL ALTER TABLE dbo.users ADD email NVARCHAR(255) NULL;
IF COL_LENGTH('dbo.users','failed_login_count') IS NULL ALTER TABLE dbo.users ADD failed_login_count INT NOT NULL CONSTRAINT DF_users_failed_login DEFAULT 0;
IF COL_LENGTH('dbo.users','locked_until') IS NULL ALTER TABLE dbo.users ADD locked_until DATETIME2 NULL;
IF OBJECT_ID('dbo.active_sessions','U') IS NULL CREATE TABLE dbo.active_sessions(id BIGINT IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,session_hash CHAR(64) NOT NULL UNIQUE,ip_address NVARCHAR(64) NULL,user_agent NVARCHAR(1000) NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),last_seen_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),expires_at DATETIME2 NULL,revoked_at DATETIME2 NULL,FOREIGN KEY(user_id) REFERENCES dbo.users(id));
IF OBJECT_ID('dbo.notification_rules','U') IS NULL CREATE TABLE dbo.notification_rules(rule_key NVARCHAR(100) PRIMARY KEY,title NVARCHAR(255) NOT NULL,is_enabled BIT NOT NULL DEFAULT 1,channel NVARCHAR(30) NOT NULL DEFAULT 'panel',updated_by BIGINT NULL,updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),FOREIGN KEY(updated_by) REFERENCES dbo.users(id));
IF OBJECT_ID('dbo.saved_filters','U') IS NULL CREATE TABLE dbo.saved_filters(id BIGINT IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,name NVARCHAR(150) NOT NULL,screen NVARCHAR(100) NOT NULL,filter_json NVARCHAR(MAX) NOT NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),FOREIGN KEY(user_id) REFERENCES dbo.users(id));
IF OBJECT_ID('dbo.workflow_transitions','U') IS NULL CREATE TABLE dbo.workflow_transitions(id INT IDENTITY PRIMARY KEY,from_step_id INT NULL,to_step_id INT NOT NULL,action_code NVARCHAR(50) NOT NULL,action_name NVARCHAR(150) NOT NULL,is_active BIT NOT NULL DEFAULT 1,FOREIGN KEY(from_step_id) REFERENCES dbo.workflow_steps(id),FOREIGN KEY(to_step_id) REFERENCES dbo.workflow_steps(id));
IF OBJECT_ID('dbo.notification_rules','U') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.notification_rules) INSERT INTO dbo.notification_rules(rule_key,title,is_enabled,channel) VALUES('critical',N'اولویت بحرانی',1,'panel'),('missing_price',N'محصول بدون قیمت',1,'panel'),('expired_price',N'قیمت منقضی',1,'panel'),('incomplete_sources',N'منابع ناقص',1,'panel'),('price_spread',N'اختلاف قیمت',1,'panel');
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_products_category_unit_status' AND object_id=OBJECT_ID('dbo.products')) CREATE INDEX IX_products_category_unit_status ON dbo.products(category_id,unit_id,is_active,status);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_prices_supplier_date' AND object_id=OBJECT_ID('dbo.product_prices')) CREATE INDEX IX_prices_supplier_date ON dbo.product_prices(supplier,price_received_at DESC);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_notifications_user_read' AND object_id=OBJECT_ID('dbo.notifications')) CREATE INDEX IX_notifications_user_read ON dbo.notifications(user_id,is_read,created_at DESC);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_audit_user_action' AND object_id=OBJECT_ID('dbo.audit_logs')) CREATE INDEX IX_audit_user_action ON dbo.audit_logs(user_id,action,created_at DESC);
GO
IF OBJECT_ID('dbo.units','U') IS NULL CREATE TABLE dbo.units(id INT IDENTITY PRIMARY KEY,name NVARCHAR(100) NOT NULL,code NVARCHAR(50) NULL,is_active BIT NOT NULL DEFAULT 1,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF OBJECT_ID('dbo.products','U') IS NULL CREATE TABLE dbo.products(id BIGINT IDENTITY PRIMARY KEY,product_code NVARCHAR(100) NOT NULL,product_name NVARCHAR(255) NOT NULL,unit_id INT NOT NULL,importance TINYINT NOT NULL DEFAULT 1,is_active BIT NOT NULL DEFAULT 1,expected_sources TINYINT NOT NULL DEFAULT 3,registered_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),CONSTRAINT FK_products_units FOREIGN KEY(unit_id) REFERENCES dbo.units(id));
IF COL_LENGTH('dbo.products','importance') IS NULL ALTER TABLE dbo.products ADD importance TINYINT NOT NULL CONSTRAINT DF_products_importance DEFAULT 1;
IF COL_LENGTH('dbo.products','is_active') IS NULL ALTER TABLE dbo.products ADD is_active BIT NOT NULL CONSTRAINT DF_products_active DEFAULT 1;
IF COL_LENGTH('dbo.products','expected_sources') IS NULL ALTER TABLE dbo.products ADD expected_sources TINYINT NOT NULL CONSTRAINT DF_products_expected_sources DEFAULT 3;
IF COL_LENGTH('dbo.products','min_sources') IS NULL ALTER TABLE dbo.products ADD min_sources TINYINT NOT NULL CONSTRAINT DF_products_min_sources DEFAULT 2;
IF COL_LENGTH('dbo.products','max_sources') IS NULL ALTER TABLE dbo.products ADD max_sources TINYINT NOT NULL CONSTRAINT DF_products_max_sources DEFAULT 3;
IF COL_LENGTH('dbo.products','status') IS NULL ALTER TABLE dbo.products ADD status NVARCHAR(30) NOT NULL CONSTRAINT DF_products_status DEFAULT 'active';
IF OBJECT_ID('dbo.product_categories','U') IS NULL CREATE TABLE dbo.product_categories(id INT IDENTITY PRIMARY KEY,name NVARCHAR(150) NOT NULL UNIQUE,description NVARCHAR(500) NULL,is_active BIT NOT NULL DEFAULT 1,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF COL_LENGTH('dbo.products','category_id') IS NULL ALTER TABLE dbo.products ADD category_id INT NULL;
IF NOT EXISTS(SELECT 1 FROM sys.foreign_keys WHERE name='FK_products_category') ALTER TABLE dbo.products ADD CONSTRAINT FK_products_category FOREIGN KEY(category_id) REFERENCES dbo.product_categories(id);
IF OBJECT_ID('dbo.product_prices','U') IS NULL CREATE TABLE dbo.product_prices(id BIGINT IDENTITY PRIMARY KEY,product_id BIGINT NOT NULL,source_no TINYINT NOT NULL,supplier NVARCHAR(255) NOT NULL,package_price DECIMAL(18,4) NOT NULL,unit_price DECIMAL(18,4) NOT NULL,price_received_at DATETIME2 NOT NULL,notes NVARCHAR(1000) NULL,created_by BIGINT NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),CONSTRAINT FK_product_prices_product FOREIGN KEY(product_id) REFERENCES dbo.products(id));
IF COL_LENGTH('dbo.product_prices','notes') IS NULL ALTER TABLE dbo.product_prices ADD notes NVARCHAR(1000) NULL;
IF COL_LENGTH('dbo.product_prices','created_by') IS NULL ALTER TABLE dbo.product_prices ADD created_by INT NULL;
IF OBJECT_ID('dbo.users','U') IS NULL CREATE TABLE dbo.users(id BIGINT IDENTITY PRIMARY KEY,username NVARCHAR(100) NOT NULL UNIQUE,name NVARCHAR(255) NOT NULL,password NVARCHAR(255) NOT NULL,is_active BIT NOT NULL DEFAULT 1,unit_id INT NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF OBJECT_ID('dbo.groups','U') IS NULL CREATE TABLE dbo.groups(id INT IDENTITY PRIMARY KEY,name NVARCHAR(150) NOT NULL UNIQUE,description NVARCHAR(500) NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF OBJECT_ID('dbo.permissions','U') IS NULL CREATE TABLE dbo.permissions(id INT IDENTITY PRIMARY KEY,code NVARCHAR(150) NOT NULL UNIQUE,name NVARCHAR(255) NOT NULL,type NVARCHAR(50) NOT NULL DEFAULT 'form',created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF OBJECT_ID('dbo.group_permissions','U') IS NULL CREATE TABLE dbo.group_permissions(group_id INT NOT NULL,permission_code NVARCHAR(150) NOT NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),PRIMARY KEY(group_id,permission_code),FOREIGN KEY(group_id) REFERENCES dbo.groups(id),FOREIGN KEY(permission_code) REFERENCES dbo.permissions(code));
IF OBJECT_ID('dbo.group_user','U') IS NULL CREATE TABLE dbo.group_user(group_id INT NOT NULL,user_id BIGINT NOT NULL,PRIMARY KEY(group_id,user_id),FOREIGN KEY(group_id) REFERENCES dbo.groups(id),FOREIGN KEY(user_id) REFERENCES dbo.users(id));
IF OBJECT_ID('dbo.user_permission_overrides','U') IS NULL CREATE TABLE dbo.user_permission_overrides(user_id BIGINT NOT NULL,permission_code NVARCHAR(150) NOT NULL,allowed BIT NOT NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),PRIMARY KEY(user_id,permission_code),FOREIGN KEY(user_id) REFERENCES dbo.users(id),FOREIGN KEY(permission_code) REFERENCES dbo.permissions(code));
IF OBJECT_ID('dbo.suppliers','U') IS NULL CREATE TABLE dbo.suppliers(id INT IDENTITY PRIMARY KEY,code NVARCHAR(100) NULL,name NVARCHAR(255) NOT NULL,phone NVARCHAR(100) NULL,email NVARCHAR(255) NULL,contact_name NVARCHAR(255) NULL,notes NVARCHAR(1000) NULL,is_active BIT NOT NULL DEFAULT 1,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF OBJECT_ID('dbo.product_sources','U') IS NULL CREATE TABLE dbo.product_sources(product_id BIGINT NOT NULL,supplier_id INT NOT NULL,source_no TINYINT NOT NULL,expected BIT NOT NULL DEFAULT 1,is_active BIT NOT NULL DEFAULT 1,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),PRIMARY KEY(product_id,supplier_id),FOREIGN KEY(product_id) REFERENCES dbo.products(id),FOREIGN KEY(supplier_id) REFERENCES dbo.suppliers(id));
IF OBJECT_ID('dbo.price_queue','U') IS NULL CREATE TABLE dbo.price_queue(id BIGINT IDENTITY PRIMARY KEY,product_id BIGINT NOT NULL UNIQUE,score DECIMAL(10,2) NOT NULL,priority_level NVARCHAR(30) NOT NULL,reason NVARCHAR(2000) NULL,status NVARCHAR(30) NOT NULL DEFAULT 'new',assigned_to BIGINT NULL,due_at DATETIME2 NULL,started_at DATETIME2 NULL,completed_at DATETIME2 NULL,result_note NVARCHAR(2000) NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),FOREIGN KEY(product_id) REFERENCES dbo.products(id),FOREIGN KEY(assigned_to) REFERENCES dbo.users(id));
IF OBJECT_ID('dbo.workflow_steps','U') IS NULL CREATE TABLE dbo.workflow_steps(id INT IDENTITY PRIMARY KEY,name NVARCHAR(150) NOT NULL,sort_order INT NOT NULL,is_active BIT NOT NULL DEFAULT 1,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF OBJECT_ID('dbo.price_workflow','U') IS NULL CREATE TABLE dbo.price_workflow(id BIGINT IDENTITY PRIMARY KEY,product_id BIGINT NOT NULL,step_id INT NOT NULL,assigned_to BIGINT NULL,status NVARCHAR(30) NOT NULL DEFAULT 'pending',comment NVARCHAR(2000) NULL,started_at DATETIME2 NULL,completed_at DATETIME2 NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),FOREIGN KEY(product_id) REFERENCES dbo.products(id),FOREIGN KEY(step_id) REFERENCES dbo.workflow_steps(id),FOREIGN KEY(assigned_to) REFERENCES dbo.users(id));
IF OBJECT_ID('dbo.audit_logs','U') IS NULL CREATE TABLE dbo.audit_logs(id BIGINT IDENTITY PRIMARY KEY,user_id BIGINT NULL,action NVARCHAR(100) NOT NULL,entity_type NVARCHAR(100) NULL,entity_id NVARCHAR(100) NULL,before_data NVARCHAR(MAX) NULL,after_data NVARCHAR(MAX) NULL,ip_address NVARCHAR(64) NULL,user_agent NVARCHAR(1000) NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),FOREIGN KEY(user_id) REFERENCES dbo.users(id));
IF OBJECT_ID('dbo.notifications','U') IS NULL CREATE TABLE dbo.notifications(id BIGINT IDENTITY PRIMARY KEY,user_id BIGINT NULL,type NVARCHAR(100) NOT NULL,title NVARCHAR(255) NOT NULL,message NVARCHAR(2000) NOT NULL,is_read BIT NOT NULL DEFAULT 0,read_at DATETIME2 NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),FOREIGN KEY(user_id) REFERENCES dbo.users(id));
IF OBJECT_ID('dbo.system_settings','U') IS NULL CREATE TABLE dbo.system_settings(setting_key NVARCHAR(150) PRIMARY KEY,setting_value NVARCHAR(MAX) NULL,updated_by BIGINT NULL,updated_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),FOREIGN KEY(updated_by) REFERENCES dbo.users(id));
IF OBJECT_ID('dbo.api_tokens','U') IS NULL CREATE TABLE dbo.api_tokens(id INT IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,name NVARCHAR(150) NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,last_used_at DATETIME2 NULL,expires_at DATETIME2 NULL,is_active BIT NOT NULL DEFAULT 1,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),FOREIGN KEY(user_id) REFERENCES dbo.users(id));
IF OBJECT_ID('dbo.import_jobs','U') IS NULL CREATE TABLE dbo.import_jobs(id BIGINT IDENTITY PRIMARY KEY,user_id BIGINT NULL,file_name NVARCHAR(255) NOT NULL,entity_type NVARCHAR(50) NOT NULL,status NVARCHAR(30) NOT NULL DEFAULT 'pending',total_rows INT NOT NULL DEFAULT 0,success_rows INT NOT NULL DEFAULT 0,error_rows INT NOT NULL DEFAULT 0,error_report NVARCHAR(MAX) NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),finished_at DATETIME2 NULL,FOREIGN KEY(user_id) REFERENCES dbo.users(id));
IF OBJECT_ID('dbo.system_jobs','U') IS NULL CREATE TABLE dbo.system_jobs(id BIGINT IDENTITY PRIMARY KEY,job_name NVARCHAR(150) NOT NULL,run_at DATETIME2 NOT NULL DEFAULT SYSDATETIME(),status NVARCHAR(30) NOT NULL,details NVARCHAR(MAX) NULL,created_at DATETIME2 NOT NULL DEFAULT SYSDATETIME());
IF NOT EXISTS(SELECT 1 FROM dbo.workflow_steps) INSERT INTO dbo.workflow_steps(name,sort_order,is_active) VALUES(N'دریافت قیمت',1,1),(N'بررسی قیمت',2,1),(N'تأیید قیمت',3,1);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_product_prices_product_date' AND object_id=OBJECT_ID('dbo.product_prices')) CREATE INDEX IX_product_prices_product_date ON dbo.product_prices(product_id,price_received_at DESC,source_no);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_products_code' AND object_id=OBJECT_ID('dbo.products')) CREATE INDEX IX_products_code ON dbo.products(product_code);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_queue_priority' AND object_id=OBJECT_ID('dbo.price_queue')) CREATE INDEX IX_queue_priority ON dbo.price_queue(score DESC,status,updated_at);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_audit_created' AND object_id=OBJECT_ID('dbo.audit_logs')) CREATE INDEX IX_audit_created ON dbo.audit_logs(created_at DESC);
GO
